<script setup lang="ts">const props=defineProps<{periodStart:string;periodEnd:string}>();const{products,orders}=useAppData();const productRows=computed(()=>{const start=new Date(`${props.periodStart}T00:00:00`),end=new Date(`${props.periodEnd}T23:59:59`),totals=new Map<string,{qty:number;revenue:number;profit:number}>();for(const order of orders.value){const date=new Date(String(order.date||''));if(Number.isNaN(date.getTime())||date<start||date>end)continue;const row=totals.get(order.product)||{qty:0,revenue:0,profit:0};row.qty+=Number(order.qty||0);row.revenue+=Number(order.gross||0);row.profit+=Number(order.profit||0);totals.set(order.product,row)}return products.value.map(product=>({...product,...(totals.get(product.name)||{qty:0,revenue:0,profit:0})})).sort((a,b)=>b.revenue-a.revenue)})</script>
<template><div class="dashboard-grid"><PanelCard title="Produtos mais relevantes" subtitle="Vendas e margem no período selecionado"><div class="table-scroll"><table class="data-table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Faturamento</th><th>Lucro</th><th>Margem cadastrada</th></tr></thead><tbody><tr v-if="!productRows.length"><td colspan="5">Nenhum produto cadastrado.</td></tr><tr v-for="item in productRows.slice(0,10)" :key="item.sku"><td><div class="table-product"><ProductThumb :type="item.thumb" :size="25"/>{{item.name}}</div></td><td>{{item.qty}}</td><td>{{formatCurrency(item.revenue)}}</td><td :class="item.profit>=0?'money-positive':'money-negative'">{{formatCurrency(item.profit)}}</td><td>{{Number(item.margin||0).toFixed(1)}}%</td></tr></tbody></table></div></PanelCard></div></template>
